#include <mutex>
#include <thread>

struct Collector {
    std::mutex m;
    long total = 0;
    bool stop = false;

    void ingest(long v) {
        std::lock_guard lock(m);
        total += v;
    }

    void drain() {
        while (!stop)
            ingest(1);
    }

    void shutdown() { stop = true; }
};

int main() {
    Collector c;
    std::thread w(&Collector::drain, &c);
    c.shutdown();
    w.join();
}

#include <mutex>
