struct Account {
    std::mutex m;
    long balance = 0;
};

void transfer(Account& from, Account& to, long amount) {
    std::lock_guard a(from.m);
    std::lock_guard b(to.m);
    from.balance -= amount;
    to.balance += amount;
}

int main() {
    Account x, y;
    std::thread t1([&] { for (int i = 0; i < 100000; ++i) transfer(x, y, 1); });
    std::thread t2([&] { for (int i = 0; i < 100000; ++i) transfer(y, x, 1); });
    t1.join();
    t2.join();
}

