#include <atomic>
#include <thread>

struct Counters {
    std::atomic<long> accepted{0};
    std::atomic<long> rejected{0};
};

Counters counters;

void accept_loop() {
    for (int i = 0; i < 1000000; ++i)
        counters.accepted.fetch_add(1, std::memory_order_relaxed);
}

void reject_loop() {
    for (int i = 0; i < 1000000; ++i)
        counters.rejected.fetch_add(1, std::memory_order_relaxed);
}

int main() {
    std::thread a(accept_loop);
    std::thread b(reject_loop);
    a.join();
    b.join();
}

#include <shared_mutex>
#include <thread>
#include <vector>

std::shared_mutex sm;
long snapshot = 0;

void reader() {
    for (int i = 0; i < 200; ++i) {
        std::shared_lock lock(sm);
        volatile long seen = snapshot;
        (void)seen;
    }
}

void writer() {
    for (int i = 0; i < 200; ++i) {
        std::unique_lock lock(sm);
        ++snapshot;
    }
}

int main() {
    std::vector<std::thread> readers;
    for (int i = 0; i < 8; ++i)
        readers.emplace_back(reader);
    std::thread w(writer);
    for (auto& t : readers)
        t.join();
    w.join();
}

