#include <mutex>
#include <thread>
#include <vector>

std::mutex m;
std::vector<int> samples;

void record(int v) {
    std::lock_guard lock(m);
    samples.push_back(v);
}

long total() {
    long sum = 0;
    for (int v : samples)
        sum += v;
    return sum;
}

int main() {
    std::thread w([] {
        for (int i = 0; i < 10000; ++i)
            record(i);
    });
    long t = total();
    w.join();
    (void)t;
}

